import { Meta, StoryObj } from "@storybook/react";
import { expect, fn, userEvent, within } from "storybook/test";
import { Notification } from "./notification";
import {
  STANDARD_NOTIFICATION,
  SUCCESS_NOTIFICATION,
  WARNING_NOTIFICATION,
} from "@/core/components/primitives/notification-center/constants/notification-types";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Notification",
  component: Notification,
  parameters: {
    docs: {
      description: {
        component:
          "Toast card rendered by the NotificationCenter: an icon and bottom border colored by `notificationType` " +
          "(standard blue info, success green check, warning red), a headline and an optional body. The whole " +
          "card is clickable and calls `onClose`; the close icon is decorative.",
      },
    },
  },
  argTypes: {
    onClose: { table: { disable: true } },
  },
  args: {
    headline: "Biljetterna är sparade",
    body: "Du hittar dem under Mina biljetter.",
    notificationType: STANDARD_NOTIFICATION,
    onClose: fn(),
  },
} satisfies Meta<typeof Notification>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantTypes: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="notificationType" variantType="prop">
      <Variant label="STANDARD_NOTIFICATION (default)">
        <Notification {...args} notificationType={STANDARD_NOTIFICATION} />
      </Variant>
      <Variant label="SUCCESS_NOTIFICATION">
        <Notification
          {...args}
          notificationType={SUCCESS_NOTIFICATION}
          headline="Betalningen gick igenom"
          body="Ett kvitto har skickats till din e-post."
        />
      </Variant>
      <Variant label="WARNING_NOTIFICATION">
        <Notification
          {...args}
          notificationType={WARNING_NOTIFICATION}
          headline="Något gick fel"
          body="Vi kunde inte spara dina biljetter. Försök igen."
        />
      </Variant>
      <Variant label="headline only (no body)">
        <Notification {...args} body={undefined} />
      </Variant>
    </ShowcaseLayout>
  ),
};

const onCloseSpy = fn();

export const TestClose: Story = {
  args: { onClose: onCloseSpy },
  // Behaviour only: clicking anywhere on the card, not just the close icon, calls onClose.
  play: async ({ canvasElement }) => {
    onCloseSpy.mockClear();
    const canvas = within(canvasElement);
    await userEvent.click(canvas.getByText("Biljetterna är sparade"));
    await expect(onCloseSpy).toHaveBeenCalledTimes(1);
  },
};
